/*
 * (port) The game's rules, built in: what Civilization II Multiplayer
 * Gold's RULES.TXT gives the game (its sections @COSMIC to @ATTITUDES), as
 * tables (src/game/rules_default.cpp, generated by tools/gen_rules.py),
 * used when there is no RULES.TXT to read.
 *
 * Where the rules come from (rules_source): a scenario's own RULES.TXT is
 * read as the original read it, names and all; else the game folder's
 * RULES.TXT, its names by key (below: a translation may replace them); else
 * these tables, their names by the same keys:
 *   rules.advance.<n>, rules.improvement.<n>, rules.unit.<n>,
 *   rules.terrain.<n>, rules.government.<n> (.male, .female: the titles),
 *   rules.leader.<n>.male / .female / .plural / .adjective,
 *   rules.leader.<n>.title.<government>.male / .female,
 *   rules.commodity.<n>, rules.order.<n> (.key: its key), rules.difficulty.<n>,
 *   rules.attitude.<n>.
 * The rules loaders are src/auto/civ.cpp's rules_load_*.
 */
#ifndef CIV2_RULES_H
#define CIV2_RULES_H

/* An advance where the rules name one (prerequisite, obsolete_by, ...):
   its AdvanceId, or one of these */
#define RULES_NIL (-1)      /* "nil": none (no prerequisite, never obsolete) */
#define RULES_NO (-2)       /* "no": never available */

/* What irrigation, mining or transformation makes of a terrain: its
   TerrainId, or one of these */
#define TERRAIN_RULE_NO (-1)        /* "no": not possible */
#define TERRAIN_RULE_YES (-2)       /* "yes": the terrain stays, with its bonus */

typedef struct RulesAdvance {
    const char *name;
    i8 ai_value;
    i8 civilized_mod;
    i8 preq[2];
    u8 epoch;
    u8 category;
} RulesAdvance;

typedef struct RulesImprovement {
    const char *name;
    u8 cost;
    u8 upkeep;
    i8 preq;
} RulesImprovement;

typedef struct RulesUnit {
    const char *name;
    i8 obsolete_by;
    u8 domain;
    u8 move;                /* as in RULES.TXT: times cosmic.road_move_mult */
    u8 range;
    u8 attack;
    u8 defense;
    u8 hit_points;          /* as in RULES.TXT: times 10 */
    u8 firepower;
    u8 cost;
    u8 hold;
    u8 role;
    i8 prerequisite;
    u16 flags;              /* UnitTypeFlag */
} RulesUnit;

typedef struct RulesTerrain {
    const char *name;
    u8 move_cost;
    u8 defense;
    u8 yields[3];
    i8 improve_to[2];       /* irrigation, mining (the 11 types only, as below) */
    u8 improve_bonus[2];
    u8 improve_turns[2];
    u8 improve_ai_govt[2];
    i8 transform_to;
} RulesTerrain;

typedef struct RulesGovernment {
    const char *name;
    const char *male_title;
    const char *female_title;
} RulesGovernment;

typedef struct RulesTitle {
    int govt;               /* 0: no more */
    const char *male;
    const char *female;
} RulesTitle;

typedef struct RulesLeader {
    const char *male_name;
    const char *female_name;
    u8 female;              /* the one that leads */
    i16 color;
    i16 city_style;
    const char *plural;
    const char *adjective;
    i8 attack;
    i8 expand;
    i8 civilize;
    RulesTitle titles[4];   /* the governments the tribe has titles of its own for */
} RulesLeader;

typedef struct RulesOrder {
    const char *name;
    const char *key;
} RulesOrder;

#define RULES_COSMIC_SIZE 0x16      /* Cosmic's fields up to reserved */
extern const Cosmic rules_cosmic;
extern const RulesAdvance rules_advances[];
extern const int rules_advance_count;
extern const RulesImprovement rules_improvements[IMP_COUNT];
extern const i8 rules_wonder_expires[WONDER_COUNT];
extern const RulesUnit rules_units[];
extern const int rules_unit_count;
extern const RulesTerrain rules_terrain[TERRAIN_RECORDS];
extern const RulesGovernment rules_governments[7];
extern const RulesLeader rules_leaders[21];
extern const char *const rules_commodities[16];
extern const RulesOrder rules_orders[12];         /* orders 1 to 12 */
extern const char *const rules_difficulties[6];
extern const char *const rules_attitudes[9];

enum {
    RULES_BUILTIN = 0,          /* these tables */
    RULES_GAME_FILE = 1,        /* the game folder's RULES.TXT, its names by key */
    RULES_SCENARIO_FILE = 2,    /* the scenario's own RULES.TXT, as the original read it */
};

/* Where the rules come from now (RULES_BUILTIN ...). */
int rules_source(void);
extern int rules_forced_source;     /* tests: the source, -1 none */

/* key's name (rules.unit.3 ...) added to the string pool as the parser
   added the name it read: padded to min_size / as it is. */
i32 rules_name(const char *key, int min_size);
i32 rules_name_pooled(const char *key);

/* A name the loaders read from the RULES.TXT line (text_next_token): the
   scenario's as it is, the game folder's by its key. */
i32 rules_read_name(const char *key, int min_size);
i32 rules_read_name_pooled(const char *key);

/* The built-in rules written out as a RULES.TXT (name: in the current
   folder), sections and values only.  0: it could not be written. */
int rules_write_default(const char *name);

#endif
